<div class="modal" id="modal"><div class="modalbox"><div class="modalhead"><div><h2>Mulai Konsultasi</h2><p>Isi kebutuhan singkat, lalu lanjut ke WhatsApp.</p></div><button class="close" onclick="closeModal()">×</button></div><form method="post"><div class="formgrid"><div class="field"><label>Nama</label><input name="name" required></div><div class="field"><label>No. WhatsApp</label><input name="phone"></div><div class="field"><label>Layanan</label><select name="service" id="service"><option>Desain Rumah</option><option>Bangun Rumah</option><option>Renovasi</option><option>Interior</option><option>3D & Rendering</option><option>Estimasi Personal</option><option>Konsultasi umum</option></select></div><div class="field"><label>Luas / ukuran</label><input name="area" placeholder="Contoh: 120 m²"></div><div class="field full"><label>Kebutuhan</label><textarea name="message" rows="4" placeholder="Contoh: tanah 8x15 m, rumah 2 lantai, gaya modern..."></textarea></div></div><button class="btn" name="consult" value="1" style="width:100%;margin-top:8px">Lanjut ke WhatsApp</button></form></div></div>
<script>const modal=document.getElementById('modal');function openModal(s){modal.classList.add('show');if(s){const x=document.getElementById('service');[...x.options].forEach(o=>{if(o.text.toLowerCase().includes(s.toLowerCase().split(' ')[0]))x.value=o.text})}}function closeModal(){modal.classList.remove('show')}modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.project').forEach(p=>p.style.display=b.dataset.filter==='all'||p.dataset.filter===p.dataset.category?'':'none')});function faq(b){b.parentElement.classList.toggle('open')}function calc(){const a=Math.max(10,Number(document.getElementById('area').value)||100),t=document.getElementById('type').value,l=Number(document.getElementById('level').value),r={desain:[80000,140000],bangun:[6500000,9000000],renovasi:[3500000,6000000],interior:[1800000,3200000]}[t],f=n=>n>=1e9?'Rp '+(n/1e9).toFixed(2).replace('.',',')+' M':'Rp '+Math.round(n/1e6)+' Jt';document.getElementById('budget').textContent=f(a*r[0]*l)+' – '+f(a*r[1]*l)}calc();</script></body></html>